import{_ as E,H as t,f as a,i}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"围炉夜话 | 你的职业起点和职业终点是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"Vue3企业级项目实战课/围炉夜话｜你的职业起点和职业终点是什么？.md","filePath":"Vue3企业级项目实战课/围炉夜话｜你的职业起点和职业终点是什么？.md","lastUpdated":1795535737000}'),p={name:"Vue3企业级项目实战课/围炉夜话｜你的职业起点和职业终点是什么？.md"};function B(_,e,s,l,n,r){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="围炉夜话-你的职业起点和职业终点是什么" tabindex="-1">围炉夜话 | 你的职业起点和职业终点是什么？ <a class="header-anchor" href="#围炉夜话-你的职业起点和职业终点是什么" aria-label="Permalink to &quot;围炉夜话 | 你的职业起点和职业终点是什么？&quot;">​</a></h1><p>你好，我是杨文坚。</p><p>今天是“围炉夜话”环节的第三期，我们聊一聊职业规划的事，正好在年底，也适合做一做今年复盘和规划，想想该怎么度过自己的职业生涯，为明年开个好头。</p><p>无论别人怎么定义人生阶段，我觉得，职场的人生阶段大致可以分成 3 层。</p><ul><li><p>做别人的事：这一阶段，要做的就是别人给的任务，执行好就好。</p></li><li><p>带人做事：有资源、有团队，能做一定选择权（但没有决策权），主要目标是让团队实现更大价值。</p></li><li><p>做自己的事：一种可能在思考公司业务发展，站在决策者⻆度思考和实施；另一种可能就是干自己想干的事情，不为别人打工。</p></li></ul><p>如果你认同我这种想法，那我就分享一下我自己是怎么干的，主要思考几个问题，具体讨论你可以看视频。</p><ul><li><p>毕业开始就考虑，自己的职业终点是什么？为此要哪些条件？</p></li><li><p>看清自己和市场，我的核心竞争力是什么？现在哪个领域更有前景，核心业务原则是什么？</p></li><li><p>在这个领域，我要积累什么，放弃什么？技术能力、人力资源、人脉。</p></li></ul><p>当然这也是我自己的想法，如果有不同观点，欢迎讨论。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Vue3%E4%BC%81%E4%B8%9A%E7%BA%A7%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25B4%25E7%2582%2589%25E5%25A4%259C%25E8%25AF%259D-%25E4%25BD%25A0%25E7%259A%2584%25E8%2581%258C%25E4%25B8%259A%25E8%25B5%25B7%25E7%2582%25B9%25E5%2592%258C%25E8%2581%258C%25E4%25B8%259A%25E7%25BB%2588%25E7%2582%25B9%25E6%2598%25AF%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Vue3%E4%BC%81%E4%B8%9A%E7%BA%A7%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%259B%25B4%25E7%2582%2589%25E5%25A4%259C%25E8%25AF%259D-%25E4%25BD%25A0%25E7%259A%2584%25E8%2581%258C%25E4%25B8%259A%25E8%25B5%25B7%25E7%2582%25B9%25E5%2592%258C%25E8%2581%258C%25E4%25B8%259A%25E7%25BB%2588%25E7%2582%25B9%25E6%2598%25AF%25E4%25BB%2580%25E4%25B9%2588%25EF%25BC%259F/1.jpeg" alt=""></a></p><p>明天就是除夕了，先预祝你节日快乐，身体健康！</p><p>这几年因为疫情原因，很多人可能都没好好过一个自在的春节了，相聚的时光最美好，这个春节，希望你能在亲朋好友的陪伴下愉快度过。我们就不安排学习任务了，节后再见。</p>',11)])])}const u=E(p,[["render",B]]);export{A as __pageData,u as default};
